(function(){
  const CURRENT_EDITION = typeof HALL_CURRENT_EDITION !== "undefined" ? HALL_CURRENT_EDITION : "WB 2026 S1";
  const HALL_PAGE_ID = "hall-da-fama";
  let renderScheduled = false;
  let loadingPromise = null;
  let cacheSignature = "";
  let indexCache = null;

  function hallExtraData(){
    try { return typeof lbffData !== "undefined" && lbffData ? lbffData : {}; }
    catch(err) { return {}; }
  }

  function hallExtraDbPlayers(){
    try { return typeof db !== "undefined" && db && Array.isArray(db.players) ? db.players : []; }
    catch(err) { return []; }
  }

  function hallExtraEditions(){
    try {
      if (typeof allEditions !== "undefined" && Array.isArray(allEditions) && allEditions.length) {
        const list = allEditions.slice();
        if (list.indexOf(CURRENT_EDITION) === -1) list.push(CURRENT_EDITION);
        return list;
      }
    } catch(err) {}
    const set = new Set();
    const data = hallExtraData();
    Object.values(data).forEach(editions => Object.keys(editions || {}).forEach(ed => set.add(ed)));
    set.add(CURRENT_EDITION);
    return Array.from(set);
  }

  function hallExtraEscape(value){
    return String(value ?? "")
      .replace(/&/g,"&amp;")
      .replace(/</g,"&lt;")
      .replace(/>/g,"&gt;")
      .replace(/\"/g,"&quot;")
      .replace(/'/g,"&#039;");
  }

  function hallExtraNormalize(value){
    const raw = String(value || "").trim();
    if (!raw) return "";
    try {
      if (typeof normalizePlayerAliasKey === "function") return normalizePlayerAliasKey(raw);
    } catch(err) {}
    return raw.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/0/g,"O").replace(/[^a-z0-9]/gi,"").toUpperCase();
  }

  function hallExtraDisplayName(name){
    try { if (typeof getDisplayName === "function") return getDisplayName(name); }
    catch(err) {}
    return name || "-";
  }

  function hallExtraCanonical(name){
    try { if (typeof getCanonicalPlayerName === "function") return getCanonicalPlayerName(name); }
    catch(err) {}
    try { if (typeof historicalAliases !== "undefined" && historicalAliases && historicalAliases[name]) return historicalAliases[name]; }
    catch(err) {}
    return name;
  }

  function hallExtraIsHallActive(){
    const page = document.getElementById(HALL_PAGE_ID);
    const hash = String(location.hash || "").replace("#", "");
    return !!page && (page.classList.contains("active") || hash === HALL_PAGE_ID);
  }

  async function hallExtraEnsureData(){
    if (Object.keys(hallExtraData()).length) return true;
    if (loadingPromise) return loadingPromise;
    loadingPromise = (async function(){
      try {
        if (typeof loadLbffData === "function") {
          await loadLbffData();
        } else {
          const url = typeof withCacheBuster === "function" ? withCacheBuster("lbffData.json") : `lbffData.json?v=${Math.floor(Date.now()/3e5)}`;
          const response = await fetch(url, { cache: "no-store" });
          if (response.ok) {
            const json = await response.json();
            try { lbffData = json; } catch(err) { window.lbffData = json; }
          }
        }
      } catch(err) {}
      return Object.keys(hallExtraData()).length > 0;
    })();
    const ok = await loadingPromise;
    loadingPromise = null;
    return ok;
  }

  function hallExtraCurrentStat(player){
    try {
      if (typeof cffHallCurrentTotalsForPlayer === "function") {
        const current = cffHallCurrentTotalsForPlayer(player);
        const k = Number(current && current.k) || 0;
        const q = Number(current && current.q) || 0;
        return {
          k,
          q,
          equipe: current && current.equipe ? current.equipe : "",
          activeName: current && current.activeName ? current.activeName : ""
        };
      }
    } catch(err) {}
    return { k: 0, q: 0, equipe: "", activeName: "" };
  }

  function hallExtraGetRawStat(data, player, edition){
    const entry = data[player] || {};
    const stat = entry[edition] || {};
    return {
      k: Number(stat.k ?? stat.kills ?? stat.abates ?? 0) || 0,
      q: Number(stat.q ?? stat.quedas ?? stat.matches ?? 0) || 0,
      equipe: stat.equipe || stat.team || ""
    };
  }

  function hallExtraBetterLeader(next, current){
    if (!current) return true;
    if (next.k !== current.k) return next.k > current.k;
    if (next.media !== current.media) return next.media > current.media;
    if (next.q !== current.q) return next.q < current.q;
    return String(next.player).localeCompare(String(current.player), "pt-BR") < 0;
  }

  function hallExtraBuildIndex(){
    const data = hallExtraData();
    const dbPlayers = hallExtraDbPlayers();
    const editions = hallExtraEditions();
    const signature = [Object.keys(data).length, dbPlayers.length, editions.join("|")].join("::");
    if (indexCache && signature === cacheSignature) return indexCache;

    const players = new Set(Object.keys(data));
    dbPlayers.forEach(p => {
      const name = p && p.jogador ? hallExtraCanonical(p.jogador) : "";
      if (name) players.add(name);
    });

    const rowsByPlayer = new Map();
    const leadersByEdition = new Map();
    const normalizeToPlayer = new Map();
    const orderedPlayers = Array.from(players).filter(Boolean).sort((a,b)=>String(a).localeCompare(String(b), "pt-BR"));

    function addNameIndex(alias, player){
      const key = hallExtraNormalize(alias);
      if (key && !normalizeToPlayer.has(key)) normalizeToPlayer.set(key, player);
    }

    orderedPlayers.forEach(player => {
      const canonical = hallExtraCanonical(player) || player;
      const dataKey = data[player] ? player : data[canonical] ? canonical : player;
      addNameIndex(player, player);
      addNameIndex(canonical, player);
      const rows = [];

      editions.forEach(edition => {
        let stat;
        if (edition === CURRENT_EDITION) {
          stat = hallExtraCurrentStat(player);
          if ((!stat.k && !stat.q) && canonical !== player) stat = hallExtraCurrentStat(canonical);
        } else {
          stat = hallExtraGetRawStat(data, dataKey, edition);
          if ((!stat.k && !stat.q) && canonical !== dataKey) stat = hallExtraGetRawStat(data, canonical, edition);
        }
        const k = Number(stat.k) || 0;
        const q = Number(stat.q) || 0;
        if (k > 0 || q > 0) {
          const row = { torneio: edition, k, q, media: q > 0 ? k / q : 0 };
          rows.push(row);
          const leader = { player, k, q, media: row.media };
          if (hallExtraBetterLeader(leader, leadersByEdition.get(edition))) leadersByEdition.set(edition, leader);
        }
      });

      rowsByPlayer.set(player, rows);
    });

    indexCache = { players: orderedPlayers, editions, rowsByPlayer, leadersByEdition, normalizeToPlayer };
    cacheSignature = signature;
    return indexCache;
  }

  function hallExtraFindPlayer(query){
    const clean = String(query || "").trim();
    if (!clean) return "";
    const index = hallExtraBuildIndex();
    if (index.rowsByPlayer.has(clean)) return clean;
    const canonical = hallExtraCanonical(clean);
    if (index.rowsByPlayer.has(canonical)) return canonical;
    const norm = hallExtraNormalize(clean);
    if (index.normalizeToPlayer.has(norm)) return index.normalizeToPlayer.get(norm);
    return index.players.find(player => {
      const p = hallExtraNormalize(player);
      return p && norm && (p.includes(norm) || norm.includes(p));
    }) || "";
  }

  function hallExtraPlayerRows(player){
    const found = hallExtraFindPlayer(player);
    if (!found) return { player: "", rows: [], totalK: 0, totalQ: 0 };
    const rows = (hallExtraBuildIndex().rowsByPlayer.get(found) || []).slice();
    const totalK = rows.reduce((sum,row)=>sum + row.k, 0);
    const totalQ = rows.reduce((sum,row)=>sum + row.q, 0);
    return { player: found, rows, totalK, totalQ };
  }

  function hallExtraPopulatePlayerList(){
    const list = document.getElementById("hall-player-summary-list");
    if (!list) return;
    const options = hallExtraBuildIndex().players.map(name => `<option value="${hallExtraEscape(name)}"></option>`).join("");
    if (list.innerHTML !== options) list.innerHTML = options;
  }

  async function cffHallRenderPlayerSummary(event){
    if (event && event.preventDefault) event.preventDefault();
    const input = document.getElementById("hall-player-summary-input");
    const result = document.getElementById("hall-player-summary-result");
    if (!result) return;
    const query = input ? input.value : "";
    if (!String(query || "").trim()) {
      result.className = "hall-player-summary-empty";
      result.innerHTML = "Digite um nome para carregar o resumo do jogador.";
      return;
    }
    result.className = "hall-player-summary-empty";
    result.innerHTML = "Carregando resumo do jogador...";
    await hallExtraEnsureData();
    const summary = hallExtraPlayerRows(query);
    if (!summary.rows.length) {
      result.className = "hall-player-summary-empty";
      result.innerHTML = "Jogador não encontrado no histórico de abates.";
      return;
    }
    const avg = summary.totalQ > 0 ? (summary.totalK / summary.totalQ).toFixed(2) : "0.00";
    result.className = "hall-player-summary-card";
    result.innerHTML = `
      <div class="hall-player-summary-head">
        <h3 class="hall-player-summary-name">${hallExtraEscape(hallExtraDisplayName(summary.player))}</h3>
      </div>
      <div class="hall-player-summary-mini">
        <span><strong>${summary.totalK}</strong><small>Abates</small></span>
        <span><strong>${summary.totalQ}</strong><small>Quedas</small></span>
        <span><strong>${avg}</strong><small>Média (geral)</small></span>
      </div>
      <div class="table-container" style="border:0; border-radius:0; margin:0;">
        <table id="table-hall-player-summary">
          <thead>
            <tr>
              <th style="text-align:left;">Torneio</th>
              <th><span class="full-name-desktop">Abates</span><span class="short-name-mobile">K</span></th>
              <th><span class="full-name-desktop">Quedas</span><span class="short-name-mobile">Q</span></th>
              <th><span class="full-name-desktop">Média de Kills</span><span class="short-name-mobile">Média</span></th>
            </tr>
          </thead>
          <tbody>
            ${summary.rows.map(row => `
              <tr>
                <td style="text-align:left; font-weight:800; color:#fff;">${hallExtraEscape(row.torneio)}</td>
                <td style="font-weight:900; color:#fff;">${row.k}</td>
                <td>${row.q}</td>
                <td style="color:var(--accent); font-weight:900;">${row.q > 0 ? row.media.toFixed(2) : "0.00"}</td>
              </tr>`).join("")}
          </tbody>
        </table>
      </div>`;
  }

  function cffHallRenderEditionLeaders(){
    const body = document.querySelector("#table-hall-edition-leaders tbody");
    if (!body) return;
    const index = hallExtraBuildIndex();
    const rows = index.editions.map(edition => ({ edition, leader: index.leadersByEdition.get(edition) })).filter(row => row.leader);
    body.innerHTML = rows.length ? rows.map(row => `
      <tr>
        <td style="text-align:left; font-weight:900; color:var(--accent);">${hallExtraEscape(row.edition)}</td>
        <td style="text-align:left; font-weight:900; color:#fff;"><span class="clickable" data-player="${hallExtraEscape(row.leader.player)}" onclick="cffHallOpenPlayerSummary(this.dataset.player)">${hallExtraEscape(hallExtraDisplayName(row.leader.player))}</span></td>
        <td style="font-weight:900; color:#fff;">${row.leader.k}</td>
        <td>${row.leader.q}</td>
        <td style="color:var(--accent); font-weight:900;">${row.leader.q > 0 ? row.leader.media.toFixed(2) : "0.00"}</td>
      </tr>`).join("") : '<tr><td colspan="5" style="color:#aaa; padding:20px;">Nenhum líder encontrado.</td></tr>';
  }

  async function cffHallOpenPlayerSummary(player){
    const input = document.getElementById("hall-player-summary-input");
    if (input) input.value = player || "";
    await cffHallRenderPlayerSummary();
    const section = document.getElementById("hall-player-summary-section");
    if (section) section.scrollIntoView({ behavior:"smooth", block:"start" });
  }

  async function cffHallExtraRenderAll(){
    if (!hallExtraIsHallActive()) return;
    const ok = await hallExtraEnsureData();
    if (!ok || !hallExtraIsHallActive()) return;
    hallExtraPopulatePlayerList();
    cffHallRenderEditionLeaders();
    const input = document.getElementById("hall-player-summary-input");
    if (input && input.value) cffHallRenderPlayerSummary();
  }

  function hallExtraScheduleRender(delay){
    if (renderScheduled) return;
    renderScheduled = true;
    setTimeout(function(){
      renderScheduled = false;
      cffHallExtraRenderAll();
    }, delay || 0);
  }

  function hallExtraPatchNavigate(){
    try {
      if (typeof navigate === "function" && !navigate.__cffHallExtraWrapped) {
        const originalNavigate = navigate;
        navigate = function(page){
          const output = originalNavigate.apply(this, arguments);
          if (String(page || "") === HALL_PAGE_ID) hallExtraScheduleRender(160);
          return output;
        };
        navigate.__cffHallExtraWrapped = true;
        if (typeof window !== "undefined") window.navigate = navigate;
      }
    } catch(err) {}
  }

  window.cffHallRenderPlayerSummary = cffHallRenderPlayerSummary;
  window.cffHallRenderEditionLeaders = cffHallRenderEditionLeaders;
  window.cffHallOpenPlayerSummary = cffHallOpenPlayerSummary;
  window.cffHallExtraRenderAll = cffHallExtraRenderAll;

  try {
    if (typeof renderHistoricalRanking === "function" && !renderHistoricalRanking.__cffHallExtraWrapped) {
      const originalRenderHistoricalRanking = renderHistoricalRanking;
      renderHistoricalRanking = function(){
        const output = originalRenderHistoricalRanking.apply(this, arguments);
        hallExtraScheduleRender(80);
        return output;
      };
      renderHistoricalRanking.__cffHallExtraWrapped = true;
    }
  } catch(err) {}

  try {
    if (typeof renderEditionRanking === "function" && !renderEditionRanking.__cffHallExtraWrapped) {
      const originalRenderEditionRanking = renderEditionRanking;
      renderEditionRanking = function(){
        const output = originalRenderEditionRanking.apply(this, arguments);
        hallExtraScheduleRender(80);
        return output;
      };
      renderEditionRanking.__cffHallExtraWrapped = true;
    }
  } catch(err) {}

  hallExtraPatchNavigate();
  setTimeout(hallExtraPatchNavigate, 500);

  document.addEventListener("click", function(event){
    const target = event.target && event.target.closest ? event.target.closest("#sb-hall-da-fama, [onclick*=\"hall-da-fama\"]") : null;
    if (target) hallExtraScheduleRender(220);
  }, true);

  window.addEventListener("hashchange", function(){
    if (String(location.hash || "").replace("#", "") === HALL_PAGE_ID) hallExtraScheduleRender(180);
  });

  document.addEventListener("DOMContentLoaded", function(){
    hallExtraPatchNavigate();
    if (hallExtraIsHallActive()) hallExtraScheduleRender(180);
  }, { once: true });
})();

;(() => {
  'use strict';

  const S2_EDITION = 'WB 2026 S2';
  const S2_STATS_URL = 'ffws-br-2026-s2/player-stats.json';
  let hallBootPromise = null;
  let s2LoadPromise = null;

  function hallS2Normalize(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    try {
      if (typeof normalizePlayerAliasKey === 'function') return normalizePlayerAliasKey(raw);
    } catch (_) {}
    return raw.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/0/g, 'O').replace(/[^a-z0-9]/gi, '').toUpperCase();
  }

  function hallS2Canonical(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    try {
      if (typeof getCanonicalPlayerName === 'function') return getCanonicalPlayerName(raw) || raw;
    } catch (_) {}
    return raw;
  }

  function hallS2Data() {
    try {
      if (typeof lbffData !== 'undefined' && lbffData) return lbffData;
    } catch (_) {}
    if (!window.lbffData) window.lbffData = {};
    return window.lbffData;
  }

  function hallS2Matches(a, b) {
    try {
      if (typeof cffPlayerNameMatches === 'function') return cffPlayerNameMatches(a, b);
    } catch (_) {}
    try {
      if (typeof checkNameMatch === 'function') return checkNameMatch(a, b);
    } catch (_) {}
    return hallS2Normalize(a) === hallS2Normalize(b);
  }

  function hallS2FindDataKey(name) {
    const data = hallS2Data();
    const canonical = hallS2Canonical(name);
    if (data[canonical]) return canonical;
    if (data[name]) return name;
    const match = Object.keys(data).find(key => hallS2Matches(key, canonical) || hallS2Matches(key, name));
    return match || canonical || name;
  }

  function hallS2RowsFromPayload(payload) {
    const aggregate = new Map();
    const add = raw => {
      if (!raw) return;
      const name = String(raw.name || raw.jogador || raw.nickname || '').trim();
      const kills = Number(raw.kills ?? raw.abates ?? raw.k ?? 0) || 0;
      const matches = Number(raw.matches ?? raw.quedas ?? raw.q ?? 0) || 0;
      const team = String(raw.team || raw.equipe || '').trim();
      if (!name || (!kills && !matches)) return;
      const canonical = hallS2Canonical(name) || name;
      const key = hallS2Normalize(canonical) || hallS2Normalize(name);
      const current = aggregate.get(key) || { name: canonical, kills: 0, matches: 0, team: '' };
      current.kills += kills;
      current.matches += matches;
      if (team) current.team = team;
      aggregate.set(key, current);
    };

    if (payload && payload.players && !Array.isArray(payload.players)) {
      Object.values(payload.players).forEach(add);
    } else if (payload && Array.isArray(payload.players)) {
      payload.players.forEach(add);
    }

    if (!aggregate.size && payload && Array.isArray(payload.entries)) {
      payload.entries.forEach(entry => add({
        name: entry.name || entry.jogador,
        team: entry.team || entry.equipe,
        kills: entry.kills ?? entry.abates,
        matches: entry.matches ?? entry.quedas ?? 1
      }));
    }
    return [...aggregate.values()];
  }

  function hallS2MergeRows(rows) {
    const data = hallS2Data();
    let merged = 0;
    rows.forEach(row => {
      const key = hallS2FindDataKey(row.name);
      if (!key) return;
      if (!data[key] || typeof data[key] !== 'object') data[key] = {};
      data[key][S2_EDITION] = {
        k: Number(row.kills) || 0,
        q: Number(row.matches) || 0,
        equipe: row.team || ''
      };
      merged += 1;
    });
    window.__cffHallS2Players = merged;
    return merged;
  }

  function hallS2RegisterEdition() {
    try {
      if (typeof allEditions !== 'undefined' && Array.isArray(allEditions) && !allEditions.includes(S2_EDITION)) {
        allEditions.push(S2_EDITION);
      }
    } catch (_) {}
    try {
      if (typeof selectedEditions !== 'undefined' && Array.isArray(selectedEditions)
        && selectedEditions.length === 1 && selectedEditions[0] === 'WB 2026 S1') {
        selectedEditions.splice(0, selectedEditions.length, S2_EDITION);
      }
    } catch (_) {}
  }

  async function hallS2Load() {
    if (s2LoadPromise) return s2LoadPromise;
    s2LoadPromise = (async () => {
      let payload = null;
      try {
        const response = await fetch(S2_STATS_URL, { cache: 'no-cache' });
        if (response.ok) payload = await response.json();
      } catch (_) {}
      if (!payload) {
        try {
          const response = await fetch('ffws-br-2026-s2/players.json', { cache: 'no-cache' });
          if (response.ok) payload = await response.json();
        } catch (_) {}
      }
      const rows = hallS2RowsFromPayload(payload || {});
      hallS2MergeRows(rows);
      hallS2RegisterEdition();
      return rows.length;
    })().finally(() => { s2LoadPromise = null; });
    return s2LoadPromise;
  }

  function hallSetLoadingState() {
    const message = '<tr><td colspan="6" style="color:var(--text-muted);padding:20px;text-align:center;">Carregando ranking histórico...</td></tr>';
    const allBody = document.querySelector('#table-history tbody');
    const editionBody = document.querySelector('#table-edition-history tbody');
    if (allBody && !allBody.children.length) allBody.innerHTML = message;
    if (editionBody && !editionBody.children.length) editionBody.innerHTML = message;
  }

  async function cffHallBoot() {
    if (hallBootPromise) return hallBootPromise;
    hallSetLoadingState();
    hallBootPromise = (async () => {
      try {
        if (typeof loadLbffData === 'function') await loadLbffData();
      } catch (_) {}
      await hallS2Load();
      try { if (typeof buildEditionFilters === 'function') buildEditionFilters(); } catch (_) {}
      try { if (typeof renderHistoricalRanking === 'function') renderHistoricalRanking(); } catch (_) {}
      try { if (typeof renderEditionRanking === 'function') renderEditionRanking(); } catch (_) {}
      try { if (typeof populateHistSelects === 'function') populateHistSelects(); } catch (_) {}
      try { if (typeof cffHallExtraRenderAll === 'function') await cffHallExtraRenderAll(); } catch (_) {}
      return true;
    })().finally(() => { hallBootPromise = null; });
    return hallBootPromise;
  }

  window.cffHallBoot = cffHallBoot;
  window.cffHallLoadS2 = hallS2Load;
})();
